// Rotates `list` left by `n` positions by concatenating list[n..] + list[..n].
// Assumes: list.len() > 0 and 0 < n < list.len().

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        new_list.len() == list.len(),
        // Result is list[n..] followed by list[..n]
        new_list@ == list@.subrange(n as int, list.len() as int)
                        + list@.subrange(0, n as int),
{
    let len = list.len();
    debug_assert!(len > 0, "list must be non-empty");
    debug_assert!(n > 0 && n < len, "n must satisfy 0 < n < list.len()");

    let mut new_list = Vec::with_capacity(len);

    // Append suffix [n..len)
    new_list.extend_from_slice(&list[n..]);

    // Append prefix [0..n)
    new_list.extend_from_slice(&list[..n]);

    // Help the verifier connect runtime slices with the spec-level postcondition.
    assert(len == list.len());
    assert(new_list.len() == len);
    assert(new_list@ == list@.subrange(n as int, len as int)
                      + list@.subrange(0, n as int));

    new_list
}

} // verus!

